"""Fail-closed source/parameter scope and coordinate provenance checks."""
from pathlib import Path
import json,hashlib,math
R=Path(__file__).resolve().parent;P=json.loads((R/'parameters.json').read_text());S=json.loads((R/'sources.json').read_text());G=json.loads((R/'osm-footprint.geojson').read_text())
origin=(120.9971573,24.7837611);ll=G['features'][0]['geometry']['coordinates'][0][:-1]
xy=[[(lon-origin[0])*111320*math.cos(math.radians(origin[1])),(lat-origin[1])*111320]for lon,lat in ll]
# Every claimed OSM corner must match the retained, freshly rechecked geographic ring.
claimed=[P['north_polygon_m'][i] for i in [0,1,2,3]]+[P['south_polygon_m'][i] for i in [0,1,2,3,4]]
errors=[min(math.dist(p,q)for q in xy)for p in claimed]
checks={'only_two_terminal_columns':sum(len(x['column_t'])for x in P.get('terminal_pilotis',[]))==2 and not P['entrance_m']['column_xy'],'unsupported_high_north_portal_absent':all(not f['portals']for f in P['facades']if f['id']=='north-east-outer'),'primary_height_10F_35p9m':P['floor_count_primary']==10 and P['main_roof_m']==35.9,'OSM_11F_conflict_explicit':'11' in P['osm']['conflict'],'claimed_OSM_vertices_match_geojson':max(errors)<1e-6,'way_version_timestamp_attribution':P['osm']['way']==1095872562 and P['osm']['version']==5 and P['osm']['timestamp']=='2023-04-18T15:09:48Z' and 'OpenStreetMap contributors' in P['osm']['attribution'],'ODbL_data_scope_explicit':P['osm']['license']=='ODbL 1.0' and 'footprint' in P['osm']['scope'],'known_3F_omission_explicit':'omitted' in S['known_connection'] and 'Third-floor' in S['known_connection'],'south_plain_explicit':'plain' in S['south_facade'],'unsupported_inner_V_notch_absent':[-48.3,-15.4] not in P['south_polygon_m'],'north_terminal_not_OSM_union_wall':min(p[1]for p in P['north_low_terminal_polygon_m'])>3.0,'fresh_replacement_not_old_approval':'Fresh' in P['recovery_statement'] and 'No previous approval' in P['recovery_statement'],'public_source_json_has_no_private_visual_paths':'visuals/' not in json.dumps(S),'base_max_150mm':max(P['base_mm'][:2])==150}
report={'passed':all(checks.values()),'checks':checks,'maximum_claimed_OSM_coordinate_error_m':max(errors),'local_projection':'x=delta_longitude*111320*cos(24.7837611deg), y=delta_latitude*111320; origin(120.9971573,24.7837611)','binding':{name:hashlib.sha256((R/name).read_bytes()).hexdigest()for name in ['build_model.py','parameters.json','sources.json','osm-footprint.geojson','requirements.txt']}}
(R/'source-provenance.json').write_text(json.dumps(report,indent=2)+'\n');print(report);assert report['passed']
